# goatty managed PowerShell startup (PowerShell 7 primary, Windows PowerShell 5.1 fallback).
# Generated by goatty and rewritten whenever a generation is built: don't edit.
# Your own goatty-only additions go in %APPDATA%\goatty\profile.ps1 (sourced near the end).
# Plain PowerShell instead: GOATTY_SHELL_MANAGED=0.
#
# Compatible with both PowerShell 7+ (pwsh.exe) and Windows PowerShell 5.1 (powershell.exe):
# avoids PS 7-only syntax (ternary, &&/||, `e, 3-arg Join-Path).

# Force UTF-8 console I/O so Nerd Font symbols, Starship, and fzf work cleanly even on PS 5.1.
try {
    $_goatty_utf8 = New-Object System.Text.UTF8Encoding($false)
    [Console]::InputEncoding = $_goatty_utf8
    [Console]::OutputEncoding = $_goatty_utf8
    $OutputEncoding = $_goatty_utf8
} catch {}

# Track PATH at each startup stage for Settings -> PATH (`path_report.rs`).
$global:_goatty_path_marks = New-Object System.Collections.Generic.List[string]
$global:_goatty_path_marks.Add("inherited`t$env:PATH")

# Load generated settings and paths.
$_goatty_here = Split-Path -Parent $MyInvocation.MyCommand.Path
$_goatty_settings_file = Join-Path $_goatty_here 'settings.ps1'
if (-not (Test-Path -LiteralPath $_goatty_settings_file)) {
    return
}
. $_goatty_settings_file

# Inside a goatty pane?
$global:_goatty_inside = ($env:TERM_PROGRAM -eq 'goatty')

# Feature status map reported by `goatty-status`: feature -> "ok<TAB>detail" | "missing" | "off"
$global:_goatty_state = [ordered]@{}
$global:_goatty_prompt = $null
$global:_goatty_psreadline = $false

function global:_goatty_ok([string]$name, [string]$detail) {
    $global:_goatty_state[$name] = "ok`t$detail"
}

function global:_goatty_on([string]$name) {
    return ($global:_goatty_features -contains $name)
}

# Escape native executable arguments containing embedded double quotes (or
# whitespace + trailing backslashes) for Windows PowerShell 5.1 / PowerShell < 7.3
# legacy argument passing while keeping PowerShell 7.3+ arguments untouched.
function global:_goatty_ps_native_arg([string]$s) {
    if ($PSVersionTable.PSVersion.Major -lt 7 -or ($PSVersionTable.PSVersion.Major -eq 7 -and $PSVersionTable.PSVersion.Minor -lt 3) -or $PSNativeCommandArgumentPassing -eq 'Legacy') {
        $s = [regex]::Replace($s, '(\\*)"', '$1$1\"')
        if ($s -match '\s') {
            $s = [regex]::Replace($s, '(\\+)$', '$1$1')
        }
    }
    return $s
}

# Cache a tool's PowerShell init output under $_goatty_cache\init\<name>-<hash>.ps1,
# keyed on PowerShell version, resolved executable path/size/mtime, extra key, and args.
# Returns the cache file path, or $null if the command failed.
function global:_goatty_cached_init {
    param(
        [string]$Name,
        [string]$Extra,
        [string]$Command,
        [string[]]$Arguments
    )
    if ([string]::IsNullOrEmpty($Name) -or $Name.IndexOfAny([char[]]@('/', '\')) -ge 0 -or $Name.StartsWith('.')) {
        return $null
    }
    $cmdInfo = Get-Command -Name $Command -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $cmdInfo -or -not $cmdInfo.Source) {
        return $null
    }
    $bin = $cmdInfo.Source
    $fi = Get-Item -LiteralPath $bin -ErrorAction SilentlyContinue
    if (-not $fi) {
        return $null
    }
    $psVer = $PSVersionTable.PSVersion.ToString()
    $key = "# goatty-cache-key: v2|$psVer|$bin|$($fi.Length):$($fi.LastWriteTimeUtc.Ticks)|$Extra|$($Arguments -join ' ')"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $hashBytes = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($key))
    } finally {
        $sha.Dispose()
    }
    $tag = ([System.BitConverter]::ToString($hashBytes).Replace('-', '').ToLowerInvariant()).Substring(0, 16)
    $cacheDir = Join-Path $_goatty_cache 'init'
    $cacheFile = Join-Path $cacheDir "$Name-$tag.ps1"

    if (Test-Path -LiteralPath $cacheFile) {
        try {
            $fs = [System.IO.File]::OpenRead($cacheFile)
            try {
                $bom = New-Object byte[] 3
                $nRead = $fs.Read($bom, 0, 3)
                $hasBom = ($nRead -eq 3 -and $bom[0] -eq 0xEF -and $bom[1] -eq 0xBB -and $bom[2] -eq 0xBF)
            } finally {
                $fs.Dispose()
            }
            if ($hasBom) {
                $firstLine = [System.IO.File]::ReadLines($cacheFile) | Select-Object -First 1
                if ($firstLine -eq $key) {
                    return $cacheFile
                }
            }
        } catch {}
    }

    try {
        $outLines = & $bin @Arguments 2>$null
        if ($LASTEXITCODE -ne 0 -or -not $outLines) {
            return $null
        }
        $code = ($outLines -join "`n")
        if ([string]::IsNullOrWhiteSpace($code)) {
            return $null
        }
    } catch {
        return $null
    }

    try {
        if (-not (Test-Path -LiteralPath $cacheDir)) {
            New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null
        }
        $tmpFile = Join-Path $cacheDir ".tmp-$Name-$tag-$PID.ps1"
        $utf8Bom = New-Object System.Text.UTF8Encoding($true)
        [System.IO.File]::WriteAllText($tmpFile, "$key`n$code`n", $utf8Bom)
        Move-Item -LiteralPath $tmpFile -Destination $cacheFile -Force
        # Prune stale cache entries for the same tool name.
        Get-ChildItem -LiteralPath $cacheDir -Filter "$Name-*.ps1" -ErrorAction SilentlyContinue | ForEach-Object {
            if ($_.FullName -ne $cacheFile -and ((Get-Date) - $_.LastWriteTime).TotalSeconds -gt 60) {
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
            }
        }
        return $cacheFile
    } catch {
        # Fallback: evaluate in-memory via caller if cache directory is read-only.
        $global:_goatty_init_code = $code
        return ''
    }
}

# --- PATH -------------------------------------------------------------------
# Folders added in goatty's settings (shell.path), then goatty's managed bin/.
function global:_goatty_append_path([string]$dir) {
    if ([string]::IsNullOrWhiteSpace($dir)) { return }
    if ($dir -eq '~') {
        $dir = $HOME
    } elseif ($dir.StartsWith('~/') -or $dir.StartsWith('~\')) {
        $dir = Join-Path $HOME $dir.Substring(2)
    }
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { return }
    $norm = $dir.TrimEnd('\', '/')
    $parts = @()
    if ($env:PATH) { $parts = $env:PATH.Split(';') }
    foreach ($p in $parts) {
        if ($p.TrimEnd('\', '/') -ieq $norm) { return }
    }
    if ([string]::IsNullOrEmpty($env:PATH)) {
        $env:PATH = $dir
    } else {
        $env:PATH = "$env:PATH;$dir"
    }
}

foreach ($_d in $_goatty_path) {
    _goatty_append_path $_d
}
$global:_goatty_path_marks.Add("settings`t$env:PATH")

if (-not [string]::IsNullOrEmpty($_goatty_bin)) {
    $normBin = $_goatty_bin.TrimEnd('\', '/')
    $hasBin = $false
    if ($env:PATH) {
        foreach ($p in $env:PATH.Split(';')) {
            if ($p.TrimEnd('\', '/') -ieq $normBin) { $hasBin = $true; break }
        }
    }
    if (-not $hasBin) {
        if ([string]::IsNullOrEmpty($env:PATH)) { $env:PATH = $_goatty_bin } else { $env:PATH = "$env:PATH;$_goatty_bin" }
    }
}
$global:_goatty_path_marks.Add("tools`t$env:PATH")

# Ensure `goattyd` works even if its directory isn't on PATH.
if (-not (Get-Command -Name 'goattyd' -ErrorAction SilentlyContinue) -and -not [string]::IsNullOrEmpty($_goatty_daemon)) {
    function global:goattyd { & $global:_goatty_daemon @args }
}

# --- Completions ------------------------------------------------------------
if (-not [string]::IsNullOrEmpty($_goatty_completions) -and (Test-Path -LiteralPath $_goatty_completions -PathType Container)) {
    Get-ChildItem -LiteralPath $_goatty_completions -Filter '*.ps1' -File -ErrorAction SilentlyContinue | ForEach-Object {
        try { . $_.FullName } catch {}
    }
}

# --- Plugins: environment & generated files ---------------------------------
$_goatty_early = Join-Path $_goatty_dir 'plugins-early.ps1'
if (Test-Path -LiteralPath $_goatty_early) { . $_goatty_early }
$global:_goatty_path_marks.Add("plugins`t$env:PATH")

# --- PSReadLine base setup (history + keys + fallback completion) -----------
try {
    if (-not (Get-Module -Name PSReadLine)) {
        Import-Module -Name PSReadLine -ErrorAction SilentlyContinue
    }
    if (Get-Module -Name PSReadLine) {
        $global:_goatty_psreadline = $true
        $psrlOpts = @{
            MaximumHistoryCount = [int]$_goatty_hist_size
            HistoryNoDuplicates = [bool]$_goatty_hist_no_dups
            BellStyle = 'None'
        }
        if ($_goatty_hist_ignore_space) {
            $psrlOpts['AddToHistoryHandler'] = {
                param([string]$line)
                if ([string]::IsNullOrEmpty($line)) { return $false }
                return (-not [char]::IsWhiteSpace($line[0]))
            }
        }
        Set-PSReadLineOption @psrlOpts -ErrorAction SilentlyContinue

        # Prefix history search on Up/Down and familiar editing keys.
        Set-PSReadLineKeyHandler -Key UpArrow -Function HistorySearchBackward -ErrorAction SilentlyContinue
        Set-PSReadLineKeyHandler -Key DownArrow -Function HistorySearchForward -ErrorAction SilentlyContinue
        Set-PSReadLineKeyHandler -Key Tab -Function MenuComplete -ErrorAction SilentlyContinue
        Set-PSReadLineKeyHandler -Key Ctrl+Backspace -Function BackwardKillWord -ErrorAction SilentlyContinue
        Set-PSReadLineKeyHandler -Key Ctrl+Delete -Function KillWord -ErrorAction SilentlyContinue
    }
} catch {}

# Shared AcceptLine and Enter handler so expansions, transient prompt redraw,
# and shell integration (OSC 133;C) cooperate without clobbering each other.
$global:_goatty_running = $false
$global:_goatty_marks = $false
$global:_goatty_exp_active = $false
$global:_goatty_transient_active = $false
$global:_goatty_render_transient = $false
$global:_goatty_transient_last_ok = $true

function global:_goatty_input_incomplete {
    try {
        $ast = $null; $tokens = $null; $parseErrors = $null; $cursor = $null
        [Microsoft.PowerShell.PSConsoleReadLine]::GetBufferState([ref]$ast, [ref]$tokens, [ref]$parseErrors, [ref]$cursor)
        if ($parseErrors) {
            foreach ($e in $parseErrors) {
                if ($e.IncompleteInput) { return $true }
            }
        }
    } catch {}
    return $false
}

function global:_goatty_accept_line {
    if ($global:_goatty_marks -and (-not (_goatty_input_incomplete))) {
        $esc = [char]27
        $bel = [char]7
        [Console]::Write("$esc]133;C$bel")
        $global:_goatty_running = $true
    }
    [Microsoft.PowerShell.PSConsoleReadLine]::AcceptLine()
}

function global:_goatty_enter_handler {
    param($key, $arg)
    $line = $null; $cursor = $null
    [Microsoft.PowerShell.PSConsoleReadLine]::GetBufferState([ref]$line, [ref]$cursor)
    if ($global:_goatty_exp_active -and $cursor -eq $line.Length -and (_goatty_exp_apply)) {
        return
    }
    $incomplete = _goatty_input_incomplete
    if ($global:_goatty_transient_active -and $global:_goatty_prompt_transient -and (-not $incomplete)) {
        $global:_goatty_render_transient = $true
        [Microsoft.PowerShell.PSConsoleReadLine]::InvokePrompt()
    }
    if ($global:_goatty_marks -and (-not $incomplete)) {
        $esc = [char]27
        $bel = [char]7
        [Console]::Write("$esc]133;C$bel")
        $global:_goatty_running = $true
    }
    [Microsoft.PowerShell.PSConsoleReadLine]::AcceptLine()
}

# --- Expansions (shell.expansions) ------------------------------------------
if ((_goatty_on 'expansions') -and (Test-Path -LiteralPath (Join-Path $_goatty_dir 'expand.ps1'))) {
    . (Join-Path $_goatty_dir 'expand.ps1')
    $expCount = 0
    if ($null -ne $global:_goatty_exp_re) { $expCount = $global:_goatty_exp_re.Count }
    _goatty_ok 'expansions' "$expCount rules"
} else {
    $global:_goatty_state['expansions'] = 'off'
}

# --- Optional user $PROFILE (shell.powershell.user_profile) -----------------
if ($_goatty_user_profile -and -not [string]::IsNullOrEmpty($PROFILE) -and (Test-Path -LiteralPath $PROFILE -PathType Leaf)) {
    try {
        $resolvedProfile = (Resolve-Path -LiteralPath $PROFILE).Path
        $resolvedDir = (Resolve-Path -LiteralPath $_goatty_dir).Path
        if (-not $resolvedProfile.StartsWith($resolvedDir, [System.StringComparison]::OrdinalIgnoreCase)) {
            . $resolvedProfile
        }
    } catch {}
    $global:_goatty_path_marks.Add("profile`t$env:PATH")
}

# --- Plugins: line editor tools (fzf -> fzf-tab -> autosuggestions) ---------
$_goatty_le = Join-Path $_goatty_dir 'plugins-line-editor.ps1'
if (Test-Path -LiteralPath $_goatty_le) { . $_goatty_le }

# --- Prompt -----------------------------------------------------------------
# Other terminals get the prompt without Nerd Font icons unless they draw
# them: prompt.icons_elsewhere (_goatty_prompt_plain: 0 always keeps them,
# 1 never, 2 automatic: terminals with Nerd Font glyphs built in).
if ($global:_goatty_prompt_plain -eq 2) {
    $_goatty_nerd_term = ($env:TERM_PROGRAM -in 'ghostty', 'WezTerm') -or ($env:TERM -in 'xterm-ghostty', 'xterm-kitty', 'wezterm')
    $global:_goatty_prompt_plain = if ($_goatty_nerd_term) { 0 } else { 1 }
}
$global:_goatty_starship_toml = 'starship.toml'
if ((-not $global:_goatty_inside) -and $global:_goatty_prompt_plain -eq 1) {
    $global:_goatty_starship_toml = 'starship-plain.toml'
    $global:_goatty_transient_ok = $_goatty_transient_ok_plain
    $global:_goatty_transient_err = $_goatty_transient_err_plain
}
$_goatty_pr = Join-Path $_goatty_dir 'plugins-prompt.ps1'
if (Test-Path -LiteralPath $_goatty_pr) { . $_goatty_pr }

# Fallback prompt when no prompt plugin loaded.
if (-not $global:_goatty_prompt) {
    if ($global:_goatty_prompt_transient) {
        $global:_goatty_transient_active = $true
    }
    function global:prompt {
        if ($global:_goatty_render_transient) {
            $global:_goatty_render_transient = $false
            return $(if ($global:_goatty_transient_last_ok) { $global:_goatty_transient_ok } else { $global:_goatty_transient_err })
        }
        $ok = $?
        $global:_goatty_transient_last_ok = $ok
        $esc = [char]27
        $cwd = $executionContext.SessionState.Path.CurrentLocation.Path
        if ($HOME -and $cwd.StartsWith($HOME, [System.StringComparison]::OrdinalIgnoreCase)) {
            $cwd = '~' + $cwd.Substring($HOME.Length)
        }
        $symColor = if ($ok) { "$esc[32m" } else { "$esc[31m" }
        $sym = if ($global:_goatty_inside -or ($global:_goatty_prompt_plain -ne 1)) { [char]0x276F } else { '>' }
        if ($global:_goatty_prompt_two_line) {
            return "$esc[34m$cwd$esc[0m`n$symColor$sym$esc[0m "
        }
        return "$esc[34m$cwd$esc[0m $symColor$sym$esc[0m "
    }
}

# --- Plugins: normal slot & user aliases ------------------------------------
$_goatty_pl = Join-Path $_goatty_dir 'plugins.ps1'
if (Test-Path -LiteralPath $_goatty_pl) { . $_goatty_pl }

$_goatty_al = Join-Path $_goatty_dir 'aliases.ps1'
if (Test-Path -LiteralPath $_goatty_al) { . $_goatty_al }

# --- Shell integration: OSC 133, OSC 7, OSC 7337, reload sentinel -----------
if ((_goatty_on 'integration') -and (Test-Path -LiteralPath (Join-Path $_goatty_dir 'integration.ps1'))) {
    . (Join-Path $_goatty_dir 'integration.ps1')
    _goatty_ok 'integration' (Join-Path $_goatty_dir 'integration.ps1')
} else {
    $global:_goatty_state['integration'] = 'off'
    # When integration is off but a prompt plugin (e.g. Starship) has transient
    # prompt enabled, wrap `prompt` lightly so `_goatty_render_transient` works.
    if ($global:_goatty_transient_active -and $global:_goatty_prompt_transient -and $global:_goatty_prompt) {
        if (($null -eq $global:_goatty_inner_prompt_fn) -or ($function:prompt.ToString() -notlike '*_goatty_transient_wrapper*')) {
            $global:_goatty_inner_prompt_fn = $function:prompt
        }
        function global:prompt {
            # marker: _goatty_transient_wrapper
            if ($global:_goatty_render_transient) {
                $global:_goatty_render_transient = $false
                return $(if ($global:_goatty_transient_last_ok) { $global:_goatty_transient_ok } else { $global:_goatty_transient_err })
            }
            $lastOk = $?
            $lastExit = $global:LASTEXITCODE
            $global:_goatty_transient_last_ok = $lastOk
            $inner = $global:_goatty_inner_prompt_fn
            if ($inner) {
                if ($lastOk) { $null = $true } else { $global:LASTEXITCODE = if ($null -ne $lastExit -and $lastExit -ne 0) { $lastExit } else { 1 } }
                $out = & $inner
                $global:LASTEXITCODE = $lastExit
                return $out
            }
            return "PS $($executionContext.SessionState.Path.CurrentLocation)> "
        }
    }
}

# --- User's goatty-only additions (%APPDATA%\goatty\profile.ps1) ------------
if (-not [string]::IsNullOrEmpty($_goatty_user_additions) -and (Test-Path -LiteralPath $_goatty_user_additions -PathType Leaf)) {
    . $_goatty_user_additions
}
$global:_goatty_path_marks.Add("additions`t$env:PATH")

# --- Plugins: last slot (syntax highlighting) -------------------------------
$_goatty_last = Join-Path $_goatty_dir 'plugins-last.ps1'
if (Test-Path -LiteralPath $_goatty_last) { . $_goatty_last }

# Bind Enter once after expansions, prompt, integration, and plugins have all
# loaded so nothing clobbers the shared handler.
if ($global:_goatty_psreadline -and ($global:_goatty_exp_active -or $global:_goatty_marks -or ($global:_goatty_transient_active -and $global:_goatty_prompt_transient))) {
    try {
        Set-PSReadLineKeyHandler -Key Enter -ScriptBlock {
            param($key, $arg)
            _goatty_enter_handler $key $arg
        } -ErrorAction SilentlyContinue
    } catch {}
}

# Record reload sentinel timestamp at startup so prompt detects `goattyd shell reload`.
$global:_goatty_reload_seen = ''
if (-not [string]::IsNullOrEmpty($_goatty_reload_sentinel) -and (Test-Path -LiteralPath $_goatty_reload_sentinel)) {
    try { $global:_goatty_reload_seen = [System.IO.File]::ReadAllText($_goatty_reload_sentinel).Trim() } catch {}
}

# --- Commands: goatty-status, goatty-setup, goatty-reload -------------------
function global:goatty-status {
    $keys = @($global:_goatty_state.Keys) | Sort-Object
    foreach ($k in $keys) {
        Write-Output "$k`t$($global:_goatty_state[$k])"
    }
}

function global:_goatty_outdated_tools {
    $out = New-Object System.Collections.Generic.List[string]
    if (-not $global:_goatty_pins) { return $out }
    foreach ($k in ($global:_goatty_pins.Keys | Sort-Object)) {
        $v = $global:_goatty_state[$k]
        if (-not $v -or -not $v.StartsWith("ok`t")) { continue }
        $detail = $v.Substring(3)
        $binDir = $global:_goatty_bin.TrimEnd('\', '/')
        if (-not $detail.StartsWith($binDir, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ownerFile = Join-Path $binDir ('.' + [System.IO.Path]::GetFileName($detail) + '.goatty')
        if (-not (Test-Path -LiteralPath $ownerFile)) { continue }
        $lines = [System.IO.File]::ReadAllLines($ownerFile)
        if ($lines.Length -ge 2 -and $lines[1].Trim() -ne $global:_goatty_pins[$k]) {
            $out.Add($k)
        }
    }
    return $out
}

function global:goatty-reload {
    $_gr_entry = Join-Path $global:_goatty_dir 'init.ps1'
    if (-not (Test-Path -LiteralPath $_gr_entry)) {
        return
    }
    # Snapshot visible functions and local variables before dot-sourcing so any
    # non-global functions, aliases, or variables defined by the user's $PROFILE,
    # profile.ps1, or plugin init scripts are promoted to global scope instead of
    # disappearing when goatty-reload returns.
    $_gr_pre_fns = New-Object System.Collections.Hashtable([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($_gr_f in (Get-ChildItem -Path 'Function:' -ErrorAction SilentlyContinue)) {
        $_gr_pre_fns[$_gr_f.Name] = $_gr_f.ScriptBlock
    }
    $_gr_skip_vars = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($_gr_v in (Get-Variable -Scope Local -ErrorAction SilentlyContinue)) {
        [void]$_gr_skip_vars.Add($_gr_v.Name)
    }
    foreach ($_gr_auto in @('?', '^', '$', '_', 'LASTEXITCODE', 'Matches', 'foreach', 'switch', 'input', 'args', 'this', 'MyInvocation', 'PSBoundParameters', 'PSCmdlet', 'PSScriptRoot', 'PSCommandPath', 'Error', 'null', 'true', 'false', 'PWD', 'HOME', 'PID', 'Host', 'PROFILE', 'PSVersionTable', 'ExecutionContext')) {
        [void]$_gr_skip_vars.Add($_gr_auto)
    }

    . $_gr_entry

    foreach ($_gr_f in (Get-ChildItem -Path 'Function:' -ErrorAction SilentlyContinue)) {
        if ((-not $_gr_pre_fns.ContainsKey($_gr_f.Name)) -or (-not [object]::ReferenceEquals($_gr_pre_fns[$_gr_f.Name], $_gr_f.ScriptBlock))) {
            Set-Item -LiteralPath ("Function:global:" + $_gr_f.Name) -Value $_gr_f.ScriptBlock -Force -ErrorAction SilentlyContinue
        }
    }
    foreach ($_gr_a in (Get-Alias -Scope Local -ErrorAction SilentlyContinue)) {
        Set-Alias -Name $_gr_a.Name -Value $_gr_a.Definition -Scope Global -Force -ErrorAction SilentlyContinue
    }
    foreach ($_gr_v in (Get-Variable -Scope Local -ErrorAction SilentlyContinue)) {
        if ($_gr_skip_vars.Contains($_gr_v.Name) -or $_gr_v.Name.StartsWith('_goatty_') -or $_gr_v.Name.StartsWith('_gr_')) {
            continue
        }
        if (($_gr_v.Options -band [System.Management.Automation.ScopedItemOptions]::Constant) -ne 0) {
            continue
        }
        Set-Variable -Name $_gr_v.Name -Value $_gr_v.Value -Scope Global -Force -ErrorAction SilentlyContinue
    }
}

function global:goatty-setup {
    $daemon = if ([string]::IsNullOrEmpty($global:_goatty_daemon)) { 'goattyd' } else { $global:_goatty_daemon }
    if ($args.Count -ge 1 -and $args[0] -eq '--dismiss') {
        & $daemon shell dismiss
        return
    }
    if ($args.Count -eq 0) {
        $todo = New-Object System.Collections.Generic.List[string]
        foreach ($d in $global:_goatty_setup_defaults) {
            if ($global:_goatty_state[$d] -eq 'missing' -and -not $todo.Contains($d)) {
                $todo.Add($d)
            }
        }
        foreach ($o in (_goatty_outdated_tools)) {
            if (-not $todo.Contains($o)) { $todo.Add($o) }
        }
        if ($todo.Count -eq 0) {
            & $daemon shell install
            if ($LASTEXITCODE -eq 0) { goatty-reload }
            return
        }
        & $daemon shell install -- @todo
        if ($LASTEXITCODE -eq 0) { goatty-reload }
        return
    }
    & $daemon shell install -- @args
    if ($LASTEXITCODE -eq 0) { goatty-reload }
}

# --- Missing/outdated-tools hint & PowerShell 5.1 hint ----------------------
try {
    $isInteractive = (-not [Console]::IsOutputRedirected)
    if ($isInteractive -and [string]::IsNullOrEmpty($env:GOATTY_GUI_SETUP) -and (-not (Test-Path -LiteralPath $_goatty_hint_marker))) {
        $esc = [char]27
        $missing = New-Object System.Collections.Generic.List[string]
        if (-not (Test-Path -LiteralPath $_goatty_offer_marker)) {
            foreach ($d in $_goatty_setup_defaults) {
                if ($global:_goatty_state[$d] -eq 'missing') { $missing.Add($d) }
            }
        }
        $outdated = _goatty_outdated_tools
        if ($missing.Count -gt 0 -or $outdated.Count -gt 0) {
            $parts = New-Object System.Collections.Generic.List[string]
            if ($missing.Count -gt 0) { $parts.Add("not installed: $($missing -join ', ')") }
            if ($outdated.Count -gt 0) { $parts.Add("outdated: $($outdated -join ', ')") }
            $action = if ($missing.Count -gt 0 -and $outdated.Count -gt 0) { 'install/update' } elseif ($outdated.Count -gt 0) { 'update' } else { 'install' }
            Write-Host ("$esc[33mgoatty:$esc[0m $($parts -join '; '). Run $esc[1mgoatty-setup$esc[0m to $action (user space, no admin), $esc[1mgoatty-setup --dismiss$esc[0m to hide this.")
        }
        if ($PSVersionTable.PSVersion.Major -lt 7) {
            Write-Host ("$esc[33mgoatty:$esc[0m running Windows PowerShell $($PSVersionTable.PSVersion.Major).$($PSVersionTable.PSVersion.Minor). Install PowerShell 7 for inline autosuggestions and faster startup: $esc[1mwinget install Microsoft.PowerShell$esc[0m")
        }
    }
} catch {}

Remove-Item -Path 'Env:GOATTY_GUI_SETUP' -ErrorAction SilentlyContinue
